SELECT * FROM user_memories
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
  AND topic = #{topic}
  AND status = #{status}
ORDER BY updated_at DESC
LIMIT 1

SELECT * FROM user_memories
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
  AND status = 'ACTIVE'
  AND (expires_at IS NULL OR expires_at > NOW())
ORDER BY updated_at DESC

SELECT COUNT(*) FROM user_memories
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
  AND status = #{status}
